mapper.select:
SELECT id, course_id, student_id, amount, paid_at, created_at
FROM sale_record
WHERE id = #{id}

SELECT s.id, s.course_id, s.student_id, s.amount, s.paid_at, s.created_at
FROM sale_record s
         JOIN course c ON s.course_id = c.id
WHERE c.creator_id = #{creatorId}

  AND s.paid_at >= #{startAt}


  AND s.paid_at < #{endAtExclusive}

ORDER BY s.paid_at

SELECT
    COALESCE(SUM(s.amount), 0) AS total_amount,
    COUNT(*) AS count
FROM sale_record s
    JOIN course c ON s.course_id = c.id
WHERE c.creator_id = #{creatorId}
  AND s.paid_at >= #{startAt}
  AND s.paid_at < #{endAtExclusive}
